<?php
namespace App\Domain\ApiHub;use App\Domain\ApiHub\Models\{TenantApiOperationLink,TenantApiWebhookDelivery,TenantApiWebhookEndpoint};use App\Domain\Shipping\Local\Models\LocalTrackingEvent;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;
final class ApiWebhookPublisher{public function tracking(LocalTrackingEvent$event):void{if(!Schema::hasTable('tenant_api_operation_links')||!Schema::hasTable('tenant_api_webhook_endpoints'))return;$event->loadMissing('shipment');$shipment=$event->shipment;if(!$shipment)return;$type=['CREATED'=>'shipment.created','READY_FOR_PICKUP'=>'shipment.ready_for_pickup','PICKED_UP'=>'shipment.picked_up','IN_TRANSIT'=>'shipment.in_transit','OUT_FOR_DELIVERY'=>'shipment.out_for_delivery','DELIVERY_FAILED'=>'shipment.delivery_failed','DELIVERED'=>'shipment.delivered'][$event->status]??null;if(!$type)return;$links=TenantApiOperationLink::where('local_shipment_id',$shipment->id)->get();foreach($links as$link){$payload=['event_id'=>(string)Str::uuid(),'type'=>$type,'created_at'=>now()->toIso8601String(),'data'=>['shipment_id'=>$shipment->uuid,'tracking'=>$shipment->tracking_number,'external_reference'=>$link->external_reference,'status'=>$shipment->status,'occurred_at'=>$event->occurred_at?->toIso8601String()]];foreach(TenantApiWebhookEndpoint::where('tenant_id',$link->tenant_id)->where('api_client_id',$link->api_client_id)->where('status','ACTIVE')->get()->filter(fn($h)=>in_array($type,$h->events,true))as$endpoint)TenantApiWebhookDelivery::firstOrCreate(['event_id'=>$payload['event_id'],'webhook_endpoint_id'=>$endpoint->id],['tenant_id'=>$link->tenant_id,'api_client_id'=>$link->api_client_id,'event_type'=>$type,'resource_type'=>'shipment','resource_uuid'=>$shipment->uuid,'payload'=>$payload,'attempt'=>0,'status'=>'PENDING','next_retry_at'=>now()]);}}}
